begin;
select plan(13);
select has_function('public','open_competition_now',array['uuid','uuid','integer']);
select ok(not has_function_privilege('authenticated','public.open_competition_now(uuid,uuid,integer)','EXECUTE'),'students cannot call the privileged opener');
insert into auth.users(id,email) values('71000000-0000-4000-8000-000000000001','open-admin@test.invalid'),('71000000-0000-4000-8000-000000000002','open-student@test.invalid');
insert into public.profiles(id,role,full_name,display_name) values('71000000-0000-4000-8000-000000000001','admin','Admin','Admin');
insert into public.profiles(id,role,student_id,full_name,display_name) values('71000000-0000-4000-8000-000000000002','student','TIME0001','Test','Test');
create temp table open_test_competition as select (public.create_competition('71000000-0000-4000-8000-000000000001','Synthetic old draft','rehearsal',clock_timestamp()-interval '2 days',clock_timestamp()-interval '1 day')->>'id')::uuid id;
select throws_ok($$select public.open_competition_now((select id from open_test_competition),'71000000-0000-4000-8000-000000000002',60)$$,'42501',null,'student cannot open a competition');
select throws_ok($$select public.open_competition_now((select id from open_test_competition),'71000000-0000-4000-8000-000000000001',0)$$,'QA422','invalid_start_window','window is bounded');
select throws_ok($$select public.open_competition_now((select id from open_test_competition),'71000000-0000-4000-8000-000000000001',60)$$,'QA409','illegal_transition','preparation cannot be skipped');
update public.competitions set state='scheduled' where id=(select id from open_test_competition);
select lives_ok($$select public.open_competition_now((select id from open_test_competition),'71000000-0000-4000-8000-000000000001',60)$$,'expired prepared draft gets a fresh admission window');
select is((select state::text from public.competitions where id=(select id from open_test_competition)),'open','competition is open');
select ok((select start_deadline_at > clock_timestamp()+interval '59 minutes' and start_deadline_at < clock_timestamp()+interval '61 minutes' from public.competitions where id=(select id from open_test_competition)),'deadline is measured from actual Open');
select is((select start_deadline_at-opens_at from public.competitions where id=(select id from open_test_competition)),interval '60 minutes','admission duration is exact');
create temp table opened_times as select opens_at,start_deadline_at from public.competitions where id=(select id from open_test_competition);
select throws_ok($$select public.open_competition_now((select id from open_test_competition),'71000000-0000-4000-8000-000000000001',120)$$,'QA409','illegal_transition','Open cannot be replayed to extend time');
select is((select start_deadline_at from public.competitions where id=(select id from open_test_competition)),(select start_deadline_at from opened_times),'replay leaves time unchanged');
select is((select count(*) from public.audit_logs where action='competition.open_window' and target_id=(select id::text from open_test_competition)),1::bigint,'Open window is audited once');
create temp table official_test_competition as select (public.create_competition('71000000-0000-4000-8000-000000000001','Synthetic official guard','official',clock_timestamp()-interval '2 days',clock_timestamp()-interval '1 day')->>'id')::uuid id;
update public.competitions set state='scheduled' where id=(select id from official_test_competition);
select throws_ok($$select public.open_competition_now((select id from official_test_competition),'71000000-0000-4000-8000-000000000001',60)$$,'QA422','bank_assessment_required','official academic assessment cannot be bypassed');
select * from finish();
rollback;
